#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    const int MAXF = 105;
    vector<long long> totalTime(MAXF, 0); // soma dos tempos de resposta
    vector<long long> recv(MAXF, 0);      // mensagens recebidas do amigo
    vector<long long> sent(MAXF, 0);      // respostas enviadas ao amigo
    vector<long long> pending(MAXF, -1);  // instante da mensagem sem resposta
    vector<char> seen(MAXF, 0);           // amigo aparece na entrada

    long long curTime = 0; // instante do último evento processado
    long long gap = 1;     // intervalo até o próximo evento (padrão 1s)

    for (int i = 0; i < n; ++i) {
        char type;
        long long x;
        cin >> type >> x;

        if (type == 'T') {
            gap = x;
        } else {
            curTime += gap;
            gap = 1;
            int f = (int)x;
            seen[f] = 1;

            if (type == 'R') {
                recv[f]++;
                pending[f] = curTime;
            } else if (type == 'E') {
                if (pending[f] >= 0) {
                    sent[f]++;
                    totalTime[f] += curTime - pending[f];
                    pending[f] = -1;
                }
            }
        }
    }

    for (int f = 1; f <= 100; ++f) {
        if (!seen[f]) continue;
        if (recv[f] == sent[f]) {
            cout << f << ' ' << totalTime[f] << '\n';
        } else {
            cout << f << ' ' << -1 << '\n';
        }
    }

    return 0;
}
